const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

// Test doubles implement the Source/Lease contract from src/source.ts.
function fixture(options = {}) {
  const calls = { opens: 0, reads: 0, closes: 0 };
  const values = ['a', 'b', null];
  const source = {
    async open() {
      calls.opens++;
      if (Object.hasOwn(options, 'openError')) throw options.openError;
      return {
        async read() {
          calls.reads++;
          if (calls.reads === 2 && Object.hasOwn(options, 'readError')) {
            throw options.readError;
          }
          return values.shift();
        },
        async close() {
          calls.closes++;
          if (Object.hasOwn(options, 'closeError')) throw options.closeError;
        },
      };
    },
  };
  const service = new EventService(source, value => {
    if (value === 'b' && Object.hasOwn(options, 'mapperError')) {
      throw options.mapperError;
    }
    return value.toUpperCase();
  });
  return { calls, service };
}

async function rejectsWith(promise, expected) {
  try {
    await promise;
  } catch (error) {
    assert.strictEqual(error, expected);
    return;
  }
  assert.fail('Expected rejection');
}

async function main() {
  {
    const { calls, service } = fixture();
    const stream = service.stream();
    assert.deepEqual(calls, { opens: 0, reads: 0, closes: 0 });
    assert.deepEqual(await stream.return(), { value: undefined, done: true });
    assert.deepEqual(calls, { opens: 0, reads: 0, closes: 0 });
  }
  {
    const { calls, service } = fixture();
    const stream = service.stream();
    assert.deepEqual(await stream.next(), { value: 'A', done: false });
    assert.deepEqual(calls, { opens: 1, reads: 1, closes: 0 });
    // Let asynchronous work settle to detect any read-ahead.
    await new Promise(resolve => setImmediate(resolve));
    assert.equal(calls.reads, 1);
    assert.deepEqual(await stream.next(), { value: 'B', done: false });
    assert.deepEqual(calls, { opens: 1, reads: 2, closes: 0 });
    assert.deepEqual(await stream.next(), { value: undefined, done: true });
    assert.deepEqual(calls, { opens: 1, reads: 3, closes: 1 });
    await stream.next();
    await stream.return();
    assert.deepEqual(calls, { opens: 1, reads: 3, closes: 1 });
  }
  {
    const { calls, service } = fixture();
    const found = [];
    for await (const value of service.stream()) found.push(value);
    assert.deepEqual(found, ['A', 'B']);
    assert.deepEqual(calls, { opens: 1, reads: 3, closes: 1 });
  }

  const closeError = new Error('close failed');
  for (const closeFails of [false, true]) {
    const options = closeFails ? { closeError } : {};
    for (const exit of ['exhaustion', 'return', 'break']) {
      const { calls, service } = fixture(options);
      const stream = service.stream();
      const finish = (async () => {
        if (exit === 'exhaustion') {
          for await (const value of stream) assert.ok(value);
        } else if (exit === 'break') {
          for await (const value of stream) {
            assert.equal(value, 'A');
            break;
          }
        } else {
          await stream.next();
          assert.deepEqual(await stream.return('returned'), { value: 'returned', done: true });
        }
      })();
      if (closeFails) await rejectsWith(finish, closeError);
      else await finish;
      assert.deepEqual(calls, { opens: 1, reads: exit === 'exhaustion' ? 3 : 1, closes: 1 });
      await stream.return();
      await stream.next();
      assert.equal(calls.closes, 1);
    }

    // Falsy thrown values also take precedence over a close error.
    for (const original of [new Error('original failure'), undefined, null, 0]) {
      for (const failure of ['readError', 'mapperError', 'injected']) {
        const { calls, service } = fixture({
          ...options,
          ...(failure === 'injected' ? {} : { [failure]: original }),
        });
        const stream = service.stream();
        assert.deepEqual(await stream.next(), { value: 'A', done: false });
        await rejectsWith(failure === 'injected' ? stream.throw(original) : stream.next(), original);
        assert.deepEqual(calls, { opens: 1, reads: failure === 'injected' ? 1 : 2, closes: 1 });
        await stream.next();
        await stream.return();
        assert.equal(calls.closes, 1);
      }
    }
  }
  {
    const openError = new Error('open failed');
    const { calls, service } = fixture({ openError });
    await rejectsWith(service.stream().next(), openError);
    assert.deepEqual(calls, { opens: 1, reads: 0, closes: 0 });
  }
  {
    const injected = new Error('unopened throw');
    const { calls, service } = fixture();
    await rejectsWith(service.stream().throw(injected), injected);
    assert.deepEqual(calls, { opens: 0, reads: 0, closes: 0 });
  }
}

module.exports = main();

